const input = $('Investigation Request').first().json;
const issue = $('Load Issue').all().map(item => item.json).find(r => r.issue_key === input.issue_key) || {};
const feature = $input.all().map(item => item.json).find(r => r.feature_key === input.output.case.feature_key) || {};
let evidence = [];
try { evidence = JSON.parse(feature.evidence || '[]'); } catch (e) { evidence = []; }
// Production files the catalog verified for this feature, both repositories, most cited first.
const counts = new Map();
for (const e of evidence) {
  const path = String(e.path || '');
  if (!path || /(^|\/)(tests?|__tests__|docs)(\/|$)|\.(md|txt)$|\.(stories|test|spec)\./i.test(path)) continue;
  const key = `${e.repository || 'backend'}: ${path}`;
  counts.set(key, (counts.get(key) || 0) + 1);
}
const knownFiles = [...counts].sort((a, b) => b[1] - a[1]).slice(0, 25).map(([key]) => key);
return [{ json: { ...input, modules: issue.modules || '', known_files: knownFiles } }];

